 const todaySessions=schedules.filter(s=>new Date(s.start_at.replace(' ','T')+'Z').toLocaleDateString('en-CA',{timeZone:'Asia/Manila'})===today&&s.status==='Published').sort((a,b)=>a.start_at.localeCompare(b.start_at));
 const navigation=member?[{group:'YOUR STUDIO',items:[['Overview',Home],['Class Schedule',CalendarDays],['My Bookings',Ticket],['My Membership',Layers],['Membership Plans',Heart],['Retreats',Sun],['My Attendance',ClipboardCheck],['My Payments',Wallet]]},{group:'ACCOUNT',items:[['Notifications',Bell],['My Profile',UserRound]]}]:[{group:'WORKSPACE',items:[['Overview',Home],['Class Schedule',CalendarDays],['Bookings',Ticket],['Attendance',ClipboardCheck]]},{group:'STUDIO MANAGEMENT',items:[['Members',Users],['Memberships',Layers],['Classes',Flower2],['Trainers',UserRound],...(me?.studio.settings.rentals_enabled?[['Rentals',DoorOpen]]:[]),...(me?.studio.settings.retreats_enabled?[['Retreats',Sun]]:[])]},{group:'BUSINESS',items:[['Finance',Wallet],['Reports',BarChart3],['System',SlidersHorizontal],['Settings',Settings]]}];
 if(loading)return <div className="loading"><Flower2 className="spin" size={40}/><h2>Finding your flow…</h2></div>;
